window.LESSON_DATA = {"schemaVersion":"2.0.0","version":"2.0.0","buildDate":"2026-08-01","course":"IB Mathematics: Applications and Interpretation SL","unit":{"number":2,"title":"Functions"},"lesson":{"number":"2.1","slug":"functions-domain-range-representations","title":"Functions, Domain, Range, and Representations","subtitle":"Connect mappings, tables, formulas, graphs and contexts while controlling valid inputs and meaningful outputs.","syllabus_focus":"Functions as models; function notation; domain and range; graphical, numerical, symbolic and contextual representations.","skill_keys":["IBAI.U2.CONCEPT"],"objectives":["Decide whether a relation defines a function and justify the decision.","Evaluate functions and find inputs that produce specified outputs.","Determine domain and range from formulas, graphs, tables and contexts.","Move fluently among representations and interpret each feature in context."],"vocab":["relation","function","input","output","domain","range","image","preimage","piecewise model","intercept"],"technology":"Use tables, graphing windows and trace/intersection tools to test representations; state domain restrictions before trusting a graph.","inquiry":"A delivery platform charges different fees at different distances. How can one model show the rule, valid distances, discontinuities and the meaning of each output?"},"slides":[{"section":"Launch","title":"Functions, Domain, Range, and Representations","html":"<div class=\"cover-grid\"><div><div class=\"cover-kicker\">IB Mathematics: Applications and Interpretation SL</div><div class=\"cover-number\">2.1</div><h1>Functions, Domain, Range, and Representations</h1><p class=\"cover-subtitle\">Connect mappings, tables, formulas, graphs and contexts while controlling valid inputs and meaningful outputs.</p><div class=\"pill-row\"><span>Inquiry</span><span>Technology</span><span>Modelling</span><span>Interpretation</span><span>Evaluation</span></div><button class=\"primary-btn route-jump\" data-go=\"practice\">Open Practice Studio</button></div><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"multiple representations\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M45 205 C110 175,145 120,210 145 S335 55,475 92\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><circle cx=\"210\" cy=\"145\" r=\"7\" fill=\"#177E89\"/><circle cx=\"335\" cy=\"92\" r=\"7\" fill=\"#D4A72C\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">multiple representations</text>\n    </svg></div></div>","kind":"cover","eyebrow":"Unit 2 · Functions"},{"section":"Launch","title":"Inquiry launch","html":"<div class=\"launch-panel\"><h2>Start with a decision</h2><p>A delivery platform charges different fees at different distances. How can one model show the rule, valid distances, discontinuities and the meaning of each output?</p><textarea class=\"student-note\" data-note=\"inquiry\" placeholder=\"Write an initial model, assumption or question before continuing.\"></textarea></div>","kind":"content","eyebrow":"Think before calculating"},{"section":"Launch","title":"Learning outcomes","html":"<div class=\"check-list\"><label><input type=checkbox data-reflect=\"obj-2.1-0\"><span>Decide whether a relation defines a function and justify the decision.</span></label><label><input type=checkbox data-reflect=\"obj-2.1-1\"><span>Evaluate functions and find inputs that produce specified outputs.</span></label><label><input type=checkbox data-reflect=\"obj-2.1-2\"><span>Determine domain and range from formulas, graphs, tables and contexts.</span></label><label><input type=checkbox data-reflect=\"obj-2.1-3\"><span>Move fluently among representations and interpret each feature in context.</span></label></div>","kind":"content","eyebrow":"By the end"},{"section":"Launch","title":"Diagnostic checkpoint","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Prior knowledge</h2><p>Coordinate axes, substitution, equation solving, percentage change and clear use of units.</p></article><article class=\"focus-card\"><h2>Quick self-check</h2><p>Can you distinguish an input restriction from a graphing-window choice? Can you explain what a parameter means in context?</p></article></div><textarea class=\"student-note\" data-note=\"diagnostic\" placeholder=\"Record one strength and one question.\"></textarea>","kind":"content","eyebrow":"Activate prior learning"},{"section":"Launch","title":"Vocabulary and notation","html":"<div class=\"vocab-grid\"><span class=vocab-chip>relation</span><span class=vocab-chip>function</span><span class=vocab-chip>input</span><span class=vocab-chip>output</span><span class=vocab-chip>domain</span><span class=vocab-chip>range</span><span class=vocab-chip>image</span><span class=vocab-chip>preimage</span><span class=vocab-chip>piecewise model</span><span class=vocab-chip>intercept</span></div><div class=\"callout\"><b>Communication standard:</b> define every variable, include units, and distinguish an exact result from a rounded interpretation.</div>","kind":"content","eyebrow":"Language matters"},{"section":"Launch","title":"IB command terms","html":"<div class=\"command-grid\"><div><b>Calculate / Find</b><span>Show relevant stages and a defensible final value.</span></div><div><b>Determine</b><span>Obtain the only possible answer.</span></div><div><b>Interpret</b><span>Connect the mathematics to variables, units and context.</span></div><div><b>Explain / Justify</b><span>Give mathematical reasons, not only a conclusion.</span></div><div><b>Evaluate / Comment</b><span>Judge validity using evidence, assumptions and limitations.</span></div><div><b>Construct / Sketch</b><span>Communicate an accurate, labelled representation.</span></div></div>","kind":"content","eyebrow":"Answer the verb"},{"section":"Launch","title":"Technology contract","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Purpose</h2><p>Use tables, graphing windows and trace/intersection tools to test representations; state domain restrictions before trusting a graph.</p></article><article class=\"focus-card\"><h2>Evidence to record</h2><p>Window/domain, equation or list entered, relevant output, units, rounding and a sentence interpreting the result.</p></article></div>","kind":"content","eyebrow":"GDC is a reasoning tool"},{"section":"Launch","title":"Lesson pathway","html":"<div class=\"workflow\"><div><b>1</b><span>Learn concepts through representations.</span></div><div><b>2</b><span>Investigate with technology.</span></div><div><b>3</b><span>Practise across four levels.</span></div><div><b>4</b><span>Complete IB tasks and a timed quiz.</span></div><div><b>5</b><span>Review evidence and mark completion.</span></div></div>","kind":"content","eyebrow":"Learn · practise · master"},{"section":"Concept cycle 1","title":"Relations and the function rule","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>A function assigns exactly one output to each allowed input. Different inputs may share an output; one input may not produce two outputs.</p></article><div class=\"formula-panel\">\\[f:x\\mapsto y\\]</div></div>","kind":"content","eyebrow":"1 of 8"},{"section":"Concept cycle 1","title":"Relations and the function rule: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"multiple representations\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M45 205 C110 175,145 120,210 145 S335 55,475 92\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><circle cx=\"210\" cy=\"145\" r=\"7\" fill=\"#177E89\"/><circle cx=\"335\" cy=\"92\" r=\"7\" fill=\"#D4A72C\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">multiple representations</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for relations and the function rule?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 1","title":"Worked example: Relations and the function rule","html":"<div class=\"worked\"><h2>A mapping sends 1→4, 2→4, 3→7. Decide whether it is a function.</h2><ol class=\"method\"><li>Each input appears once.</li><li>Repeated output 4 is allowed.</li><li>Therefore the relation is a function.</li></ol><div class=\"formula-panel\">\\[f:x\\mapsto y\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 1","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>A relation contains (−2,5), (0,1), (3,5), (0,4). Is it a function? Justify.</b></div><textarea class=\"student-note tall\" data-note=\"turn-1\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">No. The input 0 is paired with two outputs, 1 and 4.</div></details></div>","kind":"content","eyebrow":"Relations and the function rule"},{"section":"Concept cycle 1","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“Repeated y-values mean the relation is not a function.”</p><h3>Repair</h3><p>Repeated outputs are allowed; repeated inputs with different outputs are not.</p></div></div>","kind":"content","eyebrow":"Relations and the function rule"},{"section":"Concept cycle 2","title":"Function notation as a machine","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>The notation f(a) means the output produced when the input is a. It is not multiplication.</p></article><div class=\"formula-panel\">\\[f(x)=2x^2-3x+1\\]</div></div>","kind":"content","eyebrow":"2 of 8"},{"section":"Concept cycle 2","title":"Function notation as a machine: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"multiple representations\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M45 205 C110 175,145 120,210 145 S335 55,475 92\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><circle cx=\"210\" cy=\"145\" r=\"7\" fill=\"#177E89\"/><circle cx=\"335\" cy=\"92\" r=\"7\" fill=\"#D4A72C\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">multiple representations</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for function notation as a machine?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 2","title":"Worked example: Function notation as a machine","html":"<div class=\"worked\"><h2>Find f(−2) for f(x)=2x²−3x+1.</h2><ol class=\"method\"><li>Substitute x=−2 into every occurrence.</li><li>Evaluate 2(4)+6+1.</li><li>The output is 15.</li></ol><div class=\"formula-panel\">\\[f(x)=2x^2-3x+1\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 2","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>For g(t)=5−3t, calculate g(4.2).</b></div><textarea class=\"student-note tall\" data-note=\"turn-2\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">g(4.2)=5−12.6=−7.6.</div></details></div>","kind":"content","eyebrow":"Function notation as a machine"},{"section":"Concept cycle 2","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“f(3) means f×3.”</p><h3>Repair</h3><p>f is the name of the rule; f(3) is an output value.</p></div></div>","kind":"content","eyebrow":"Function notation as a machine"},{"section":"Concept cycle 3","title":"Domain from structure","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>The domain is the set of inputs for which the rule is defined. Denominators cannot be zero and even roots require non-negative radicands.</p></article><div class=\"formula-panel\">\\[h(x)=\\frac{\\sqrt{x-2}}{x-7}\\]</div></div>","kind":"content","eyebrow":"3 of 8"},{"section":"Concept cycle 3","title":"Domain from structure: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"multiple representations\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M45 205 C110 175,145 120,210 145 S335 55,475 92\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><circle cx=\"210\" cy=\"145\" r=\"7\" fill=\"#177E89\"/><circle cx=\"335\" cy=\"92\" r=\"7\" fill=\"#D4A72C\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">multiple representations</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for domain from structure?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 3","title":"Worked example: Domain from structure","html":"<div class=\"worked\"><h2>State the domain of h(x)=√(x−2)/(x−7).</h2><ol class=\"method\"><li>Require x−2≥0, so x≥2.</li><li>Exclude x=7 because the denominator is zero.</li><li>Domain: [2,7)∪(7,∞).</li></ol><div class=\"formula-panel\">\\[h(x)=\\frac{\\sqrt{x-2}}{x-7}\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 3","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>State the domain of p(x)=√(12−3x).</b></div><textarea class=\"student-note tall\" data-note=\"turn-3\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">12−3x≥0, so x≤4.</div></details></div>","kind":"content","eyebrow":"Domain from structure"},{"section":"Concept cycle 3","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“A calculator graph shows a point, so the input must be valid.”</p><h3>Repair</h3><p>A graphing window may hide restrictions or connect across gaps; determine domain analytically and contextually.</p></div></div>","kind":"content","eyebrow":"Domain from structure"},{"section":"Concept cycle 4","title":"Range from evidence","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>The range is the set of outputs actually produced. Endpoints, turning points, asymptotes and domain restrictions all affect it.</p></article><div class=\"formula-panel\">\\[y=(x-3)^2+2,\\quad -1\\le x\\le5\\]</div></div>","kind":"content","eyebrow":"4 of 8"},{"section":"Concept cycle 4","title":"Range from evidence: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"multiple representations\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M45 205 C110 175,145 120,210 145 S335 55,475 92\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><circle cx=\"210\" cy=\"145\" r=\"7\" fill=\"#177E89\"/><circle cx=\"335\" cy=\"92\" r=\"7\" fill=\"#D4A72C\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">multiple representations</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for range from evidence?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 4","title":"Worked example: Range from evidence","html":"<div class=\"worked\"><h2>Find the range of y=(x−3)²+2 on −1≤x≤5.</h2><ol class=\"method\"><li>The minimum is 2 at x=3.</li><li>At x=−1, y=18; at x=5, y=6.</li><li>Range: [2,18].</li></ol><div class=\"formula-panel\">\\[y=(x-3)^2+2,\\quad -1\\le x\\le5\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 4","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>Find the range of y=−2x+7 for 1≤x≤6.</b></div><textarea class=\"student-note tall\" data-note=\"turn-4\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">Outputs decrease from 5 to −5, so the range is [−5,5].</div></details></div>","kind":"content","eyebrow":"Range from evidence"},{"section":"Concept cycle 4","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“The range is found by copying the domain.”</p><h3>Repair</h3><p>The range must be calculated or read from output values.</p></div></div>","kind":"content","eyebrow":"Range from evidence"},{"section":"Concept cycle 5","title":"Four representations of one model","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>A table gives sampled values, a graph reveals global shape, a formula supports calculation, and a verbal description gives meaning and constraints.</p></article><div class=\"formula-panel\">\\[C(n)=18+4.5n\\]</div></div>","kind":"content","eyebrow":"5 of 8"},{"section":"Concept cycle 5","title":"Four representations of one model: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"multiple representations\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M45 205 C110 175,145 120,210 145 S335 55,475 92\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><circle cx=\"210\" cy=\"145\" r=\"7\" fill=\"#177E89\"/><circle cx=\"335\" cy=\"92\" r=\"7\" fill=\"#D4A72C\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">multiple representations</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for four representations of one model?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 5","title":"Worked example: Four representations of one model","html":"<div class=\"worked\"><h2>Interpret the slope and intercept in C(n)=18+4.5n for a taxi fare.</h2><ol class=\"method\"><li>18 is the fixed starting charge.</li><li>4.5 is the cost per kilometre.</li><li>Units make the interpretation complete.</li></ol><div class=\"formula-panel\">\\[C(n)=18+4.5n\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 5","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>A table increases by 12 each hour and starts at 40. Write a model and interpret both parameters.</b></div><textarea class=\"student-note tall\" data-note=\"turn-5\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">y=40+12t; 40 is the initial amount and 12 is the increase per hour.</div></details></div>","kind":"content","eyebrow":"Four representations of one model"},{"section":"Concept cycle 5","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“A formula alone is a complete model.”</p><h3>Repair</h3><p>A model also needs variable definitions, units, domain and assumptions.</p></div></div>","kind":"content","eyebrow":"Four representations of one model"},{"section":"Concept cycle 6","title":"Intercepts and sign","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>An x-intercept solves f(x)=0; the y-intercept is f(0). Sign describes whether outputs are positive, zero or negative.</p></article><div class=\"formula-panel\">\\[f(x)=(x-2)(x+5)\\]</div></div>","kind":"content","eyebrow":"6 of 8"},{"section":"Concept cycle 6","title":"Intercepts and sign: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"multiple representations\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M45 205 C110 175,145 120,210 145 S335 55,475 92\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><circle cx=\"210\" cy=\"145\" r=\"7\" fill=\"#177E89\"/><circle cx=\"335\" cy=\"92\" r=\"7\" fill=\"#D4A72C\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">multiple representations</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for intercepts and sign?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 6","title":"Worked example: Intercepts and sign","html":"<div class=\"worked\"><h2>Find the intercepts of f(x)=(x−2)(x+5).</h2><ol class=\"method\"><li>Roots are x=2 and x=−5.</li><li>f(0)=−10.</li><li>Intercepts: (2,0), (−5,0), (0,−10).</li></ol><div class=\"formula-panel\">\\[f(x)=(x-2)(x+5)\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 6","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>For g(x)=3x−12, state both axis intercepts.</b></div><textarea class=\"student-note tall\" data-note=\"turn-6\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">x-intercept (4,0); y-intercept (0,−12).</div></details></div>","kind":"content","eyebrow":"Intercepts and sign"},{"section":"Concept cycle 6","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“The y-intercept is obtained by setting y=0.”</p><h3>Repair</h3><p>Set x=0 for the y-intercept; set y=0 for x-intercepts.</p></div></div>","kind":"content","eyebrow":"Intercepts and sign"},{"section":"Concept cycle 7","title":"Piecewise functions","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>A piecewise model uses different rules on different parts of its domain. Endpoint symbols determine which rule owns a boundary.</p></article><div class=\"formula-panel\">\\[P(t)=\\begin{cases}8,&0\\le t\\le2\\\\8+3(t-2),&t>2\\end{cases}\\]</div></div>","kind":"content","eyebrow":"7 of 8"},{"section":"Concept cycle 7","title":"Piecewise functions: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"multiple representations\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M45 205 C110 175,145 120,210 145 S335 55,475 92\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><circle cx=\"210\" cy=\"145\" r=\"7\" fill=\"#177E89\"/><circle cx=\"335\" cy=\"92\" r=\"7\" fill=\"#D4A72C\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">multiple representations</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for piecewise functions?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 7","title":"Worked example: Piecewise functions","html":"<div class=\"worked\"><h2>Evaluate P(2) and P(5).</h2><ol class=\"method\"><li>At t=2 use the first branch: P(2)=8.</li><li>At t=5 use the second branch.</li><li>P(5)=8+3(3)=17.</li></ol><div class=\"formula-panel\">\\[P(t)=\\begin{cases}8,&0\\le t\\le2\\\\8+3(t-2),&t>2\\end{cases}\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 7","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>A parking fee is QAR 6 for the first hour and QAR 4 per additional hour. Write a piecewise model for 0<t≤5.</b></div><textarea class=\"student-note tall\" data-note=\"turn-7\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">C(t)=6 for 0<t≤1 and C(t)=6+4(t−1) for 1<t≤5.</div></details></div>","kind":"content","eyebrow":"Piecewise functions"},{"section":"Concept cycle 7","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“Both pieces can include the same boundary even when they give different outputs.”</p><h3>Repair</h3><p>A function must have one output at each input; endpoint conventions must be consistent.</p></div></div>","kind":"content","eyebrow":"Piecewise functions"},{"section":"Concept cycle 8","title":"Technology, windows and preimages","html":"<div class=\"concept-grid\"><article class=\"focus-card\"><h2>Core idea</h2><p>Trace finds outputs, solve/intersect finds preimages, and a suitable window must include the relevant domain and range.</p></article><div class=\"formula-panel\">\\[f(x)=0.4x^3-3x+1\\]</div></div>","kind":"content","eyebrow":"8 of 8"},{"section":"Concept cycle 8","title":"Technology, windows and preimages: representations","html":"<div class=\"two-col\"><div><svg class=\"concept-visual\" viewBox=\"0 0 520 250\" role=\"img\" aria-label=\"multiple representations\">\n      <rect width=\"520\" height=\"250\" rx=\"24\" fill=\"#F4EFE8\"/>\n      <g stroke=\"#D9D2C8\" stroke-width=\"1\"><line x1=\"60\" y1=\"25\" x2=\"60\" y2=\"225\"/><line x1=\"100\" y1=\"25\" x2=\"100\" y2=\"225\"/><line x1=\"140\" y1=\"25\" x2=\"140\" y2=\"225\"/><line x1=\"180\" y1=\"25\" x2=\"180\" y2=\"225\"/><line x1=\"220\" y1=\"25\" x2=\"220\" y2=\"225\"/><line x1=\"260\" y1=\"25\" x2=\"260\" y2=\"225\"/><line x1=\"300\" y1=\"25\" x2=\"300\" y2=\"225\"/><line x1=\"340\" y1=\"25\" x2=\"340\" y2=\"225\"/><line x1=\"380\" y1=\"25\" x2=\"380\" y2=\"225\"/><line x1=\"420\" y1=\"25\" x2=\"420\" y2=\"225\"/><line x1=\"460\" y1=\"25\" x2=\"460\" y2=\"225\"/><line x1=\"500\" y1=\"25\" x2=\"500\" y2=\"225\"/><line x1=\"30\" y1=\"35\" x2=\"500\" y2=\"35\"/><line x1=\"30\" y1=\"65\" x2=\"500\" y2=\"65\"/><line x1=\"30\" y1=\"95\" x2=\"500\" y2=\"95\"/><line x1=\"30\" y1=\"125\" x2=\"500\" y2=\"125\"/><line x1=\"30\" y1=\"155\" x2=\"500\" y2=\"155\"/><line x1=\"30\" y1=\"185\" x2=\"500\" y2=\"185\"/><line x1=\"30\" y1=\"215\" x2=\"500\" y2=\"215\"/></g>\n      <line x1=\"30\" y1=\"190\" x2=\"500\" y2=\"190\" stroke=\"#17324D\" stroke-width=\"3\"/><line x1=\"80\" y1=\"225\" x2=\"80\" y2=\"25\" stroke=\"#17324D\" stroke-width=\"3\"/>\n      <path d=\"M45 205 C110 175,145 120,210 145 S335 55,475 92\" fill=\"none\" stroke=\"#7A1733\" stroke-width=\"5\" stroke-linecap=\"round\"/><circle cx=\"210\" cy=\"145\" r=\"7\" fill=\"#177E89\"/><circle cx=\"335\" cy=\"92\" r=\"7\" fill=\"#D4A72C\"/>\n      <text x=\"490\" y=\"181\" fill=\"#17324D\">x</text><text x=\"90\" y=\"38\" fill=\"#17324D\">y</text><text x=\"260\" y=\"235\" text-anchor=\"middle\" fill=\"#5D6A75\">multiple representations</text>\n    </svg></div><article class=\"focus-card\"><h2>Read the representation</h2><p>Connect the formula, graph, table or context. Ask: what are the inputs, outputs, restrictions, key features and units for technology, windows and preimages?</p></article></div>","kind":"content","eyebrow":"Rule of four"},{"section":"Concept cycle 8","title":"Worked example: Technology, windows and preimages","html":"<div class=\"worked\"><h2>Explain how to find the inputs for which f(x)=5 using technology.</h2><ol class=\"method\"><li>Graph y=f(x) and y=5.</li><li>Use intersection/solve on the intended domain.</li><li>Report all relevant x-values with justified precision.</li></ol><div class=\"formula-panel\">\\[f(x)=0.4x^3-3x+1\\]</div></div>","kind":"content","eyebrow":"Model a complete response"},{"section":"Concept cycle 8","title":"Student turn","html":"<div class=\"student-turn\"><div class=\"prompt\"><b>Why might the default −10≤x≤10 window miss an important feature of a model valid for 0≤x≤500?</b></div><textarea class=\"student-note tall\" data-note=\"turn-8\" placeholder=\"Show your method, units and interpretation.\"></textarea><details class=\"solution-preview\"><summary>Reveal a model response</summary><div class=\"solution-panel\">Most of the contextual domain is outside the window, so intersections or turning behaviour may be hidden.</div></details></div>","kind":"content","eyebrow":"Technology, windows and preimages"},{"section":"Concept cycle 8","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h2>Common error</h2><p>“No visible intersection means no solution.”</p><h3>Repair</h3><p>First check the window, domain and numerical scale.</p></div></div>","kind":"content","eyebrow":"Technology, windows and preimages"},{"section":"Technology laboratory","title":"Interactive laboratory","html":"<div class=\"lab\"><h2>Change a parameter. Predict first. Test second.</h2><p>Use tables, graphing windows and trace/intersection tools to test representations; state domain restrictions before trusting a graph.</p><div id=\"lesson-lab\" data-lab=\"2.1\"></div></div>","kind":"lab","eyebrow":"Technology with purpose"},{"section":"Technology laboratory","title":"GDC workflow","html":"<div class=\"workflow\"><div><b>1</b><span>Define variables and the valid domain.</span></div><div><b>2</b><span>Enter the model accurately.</span></div><div><b>3</b><span>Choose a window or list that reveals relevant behaviour.</span></div><div><b>4</b><span>Use trace, intersect, regression or solve.</span></div><div><b>5</b><span>Verify and interpret the output.</span></div></div>","kind":"content","eyebrow":"Repeatable process"},{"section":"Technology laboratory","title":"Interpreting calculator output","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Raw output</h2><p>A decimal, regression equation or graph feature is not yet a complete answer.</p></article><article class=\"focus-card\"><h2>IB response</h2><p>State the method, round appropriately, include units, select the contextual solution and explain what it means.</p></article></div>","kind":"content","eyebrow":"Technology → mathematics → context"},{"section":"Technology laboratory","title":"Precision and validation","html":"<div class=\"callout\"><b>Avoid premature rounding.</b> Store or retain full-precision values until the final line. Then test the result in the original model and check whether it belongs to the domain.</div><textarea class=\"student-note\" data-note=\"technology-check\" placeholder=\"Write the validation check you would use for this lesson.\"></textarea>","kind":"content","eyebrow":"Reliable evidence"},{"section":"Case study","title":"Case-study brief","html":"<div class=\"investigation\"><h2>A delivery platform charges different fees at different distances. How can one model show the rule, valid distances, discontinuities and the meaning of each output?</h2><p>Build a model, make at least two assumptions, use technology, and identify evidence that could reject your model.</p></div>","kind":"content","eyebrow":"Mini investigation"},{"section":"Case study","title":"Data and model choice","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Evidence</h2><p>Use numerical, graphical and contextual information. Look for constant differences, ratios, turning points, asymptotes, residual structure or restrictions.</p></article><article class=\"focus-card\"><h2>Choice</h2><p>Select the simplest defensible model. A more complex model requires stronger evidence and clearer parameter interpretation.</p></article></div>","kind":"content","eyebrow":"Model selection"},{"section":"Case study","title":"Decision and interpretation","html":"<div class=\"student-turn\"><h2>Write the decision sentence</h2><p>“According to the model, … because … . This conclusion is valid for … and assumes … .”</p><textarea class=\"student-note tall\" data-note=\"case-decision\" placeholder=\"Complete the sentence for the inquiry context.\"></textarea></div>","kind":"content","eyebrow":"Communicate like an IB student"},{"section":"Case study","title":"Evaluate and extend","html":"<div class=\"reflection-grid\"><div><h2>Validity</h2><p>Does the model reproduce known data and respect physical limits?</p></div><div><h2>Sensitivity</h2><p>How much does the conclusion change when inputs or parameters change?</p></div><div><h2>Extension</h2><p>What additional data or alternative model would strengthen the decision?</p></div></div>","kind":"content","eyebrow":"Reflection is mathematics"},{"section":"Communication","title":"Full-mark response checklist","html":"<div class=\"check-list\"><label><input type=checkbox data-reflect=\"comm-1\"><span>I used the command term at the required depth.</span></label><label><input type=checkbox data-reflect=\"comm-2\"><span>I showed the equation, substitution or technology evidence.</span></label><label><input type=checkbox data-reflect=\"comm-3\"><span>I used correct notation, units and rounding.</span></label><label><input type=checkbox data-reflect=\"comm-4\"><span>I interpreted the result and addressed restrictions.</span></label><label><input type=checkbox data-reflect=\"comm-5\"><span>I evaluated assumptions when the question required judgment.</span></label></div>","kind":"content","eyebrow":"Before submitting"},{"section":"Communication","title":"Theory of Knowledge connection","html":"<div class=\"explain-prompt\"><h2>When does a useful model count as knowledge?</h2><p>Discuss whether predictive accuracy, explanatory mechanism, transparent assumptions and reproducibility contribute differently to trust.</p><textarea class=\"student-note tall\" data-note=\"tok\" placeholder=\"Write a claim, counterclaim and example.\"></textarea></div>","kind":"content","eyebrow":"TOK"},{"section":"Communication","title":"Internal assessment connection","html":"<div class=\"two-col\"><article class=\"focus-card\"><h2>Possible exploration move</h2><p>Collect or source data, justify a function family, estimate parameters, analyse residuals and discuss limitations.</p></article><article class=\"focus-card\"><h2>Personal engagement</h2><p>Make a mathematical decision in a context you genuinely understand; do not merely reproduce calculator output.</p></article></div>","kind":"content","eyebrow":"IA thinking"},{"section":"Communication","title":"Exam strategy","html":"<div class=\"workflow\"><div><b>Read</b><span>Underline command terms, domain and requested precision.</span></div><div><b>Plan</b><span>Choose algebra, graph, table or regression deliberately.</span></div><div><b>Execute</b><span>Record method and retain full precision.</span></div><div><b>Interpret</b><span>Return to context and units.</span></div><div><b>Check</b><span>Substitute, compare or inspect residuals.</span></div></div>","kind":"content","eyebrow":"Five moves"},{"section":"Closure","title":"Mixed exit ticket","html":"<div class=\"exit-grid\"><div><b>Represent</b><span>Give two representations of one idea from Functions, Domain, Range, and Representations.</span></div><div><b>Calculate</b><span>Create and solve a numerical example.</span></div><div><b>Interpret</b><span>Explain a parameter or feature with units.</span></div><div><b>Evaluate</b><span>State one assumption and one limitation.</span></div></div><textarea class=\"student-note tall\" data-note=\"exit\" placeholder=\"Complete all four prompts.\"></textarea>","kind":"content","eyebrow":"Synthesis"},{"section":"Closure","title":"Mastery checklist","html":"<div class=\"check-list\"><label><input type=checkbox data-reflect=\"master-2.1-0\"><span>Decide whether a relation defines a function and justify the decision.</span></label><label><input type=checkbox data-reflect=\"master-2.1-1\"><span>Evaluate functions and find inputs that produce specified outputs.</span></label><label><input type=checkbox data-reflect=\"master-2.1-2\"><span>Determine domain and range from formulas, graphs, tables and contexts.</span></label><label><input type=checkbox data-reflect=\"master-2.1-3\"><span>Move fluently among representations and interpret each feature in context.</span></label></div>","kind":"content","eyebrow":"Can you do this independently?"},{"section":"Closure","title":"Next route","html":"<div class=\"connection-grid\"><button class=\"primary-btn route-jump\" data-go=\"practice\">Practice Studio · 60 questions</button><button class=\"secondary-btn route-jump\" data-go=\"exam\">IB Tasks · 3 extended responses</button><button class=\"secondary-btn route-jump\" data-go=\"quiz\">Timed Quiz · 12 questions</button><button class=\"secondary-btn route-jump\" data-go=\"review\">Mastery review</button></div>","kind":"content","eyebrow":"Choose evidence"},{"section":"Closure","title":"Lesson complete","html":"<div class=\"launch-panel\"><h2>Functions, Domain, Range, and Representations</h2><p>You have completed the Learn route. Use Practice Studio, IB Tasks and the independent quiz to turn familiarity into durable evidence.</p><button class=\"primary-btn route-jump\" data-go=\"review\">Open mastery and mark completion</button></div>","kind":"content","eyebrow":"Bridge to practice"}],"practice":[{"id":"IBAI-2.1-P01","level":"Foundation","prompt":"Which relation is a function?","answer":"{(−2,7),(0,7),(4,1)}","solution":"The second relation assigns exactly one output to each input. Repeated output 7 is allowed.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["{(1,2),(1,5),(3,4)}","{(−2,7),(0,7),(4,1)}","{(3,1),(3,1),(3,8)}","x²+y²=9"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.1-P02","level":"Foundation","prompt":"For \\(f(x)=3x-7\\), calculate \\(f(5)\\).","answer":"\\(8\\)","solution":"Substitute x=5: 3(5)−7=8.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":8.0,"tolerance":8e-05}},{"id":"IBAI-2.1-P03","level":"Foundation","prompt":"For \\(g(t)=2t^2+t-4\\), calculate \\(g(-3)\\).","answer":"\\(11\\)","solution":"g(−3)=2(9)−3−4=11.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":11.0,"tolerance":0.00011}},{"id":"IBAI-2.1-P04","level":"Foundation","prompt":"State the domain of \\(h(x)=\\sqrt{x+6}\\).","answer":"\\(x\\ge-6\\)","solution":"Require x+6≥0.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"text","accepted":["x>=-6","x ≥ -6","[-6,infinity)","[-6,∞)"]}},{"id":"IBAI-2.1-P05","level":"Foundation","prompt":"State the excluded value in the domain of \\(p(x)=\\frac{5}{2x-8}\\).","answer":"\\(x\\ne4\\)","solution":"The denominator is zero at x=4.","marks":2,"calculator":"No GDC required","command":"Write down","hint":"","tags":[],"check":{"mode":"text","accepted":["4","x=4","x ≠ 4"]}},{"id":"IBAI-2.1-P06","level":"Foundation","prompt":"The outputs in a table are 4, 9, 9, 15 and 22. State the range as a set.","answer":"\\(\\{4,9,15,22\\}\\)","solution":"A set lists each output once.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"text","accepted":["{4,9,15,22}","4,9,15,22"]}},{"id":"IBAI-2.1-P07","level":"Foundation","prompt":"Find the y-intercept value of \\(y=7-2x\\).","answer":"\\(7\\)","solution":"Set x=0, giving y=7.","marks":2,"calculator":"No GDC required","command":"Find","hint":"","tags":[],"check":{"mode":"number","value":7.0,"tolerance":7.000000000000001e-05}},{"id":"IBAI-2.1-P08","level":"Foundation","prompt":"Find the x-intercept of \\(y=4x-20\\).","answer":"\\(5\\)","solution":"Set y=0: 4x−20=0, so x=5.","marks":2,"calculator":"No GDC required","command":"Find","hint":"","tags":[],"check":{"mode":"number","value":5.0,"tolerance":5e-05}},{"id":"IBAI-2.1-P09","level":"Foundation","prompt":"Let \\(P(t)=6\\) for \\(0<t\\le2\\), and \\(P(t)=6+4(t-2)\\) for \\(t>2\\). Calculate \\(P(5)\\).","answer":"\\(18\\)","solution":"Use the second branch: 6+4(3)=18.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":18.0,"tolerance":0.00018}},{"id":"IBAI-2.1-P10","level":"Foundation","prompt":"For \\(f(x)=5x+1\\), find the input whose output is 31.","answer":"\\(6\\)","solution":"Solve 5x+1=31, so x=6.","marks":2,"calculator":"No GDC required","command":"Find","hint":"","tags":[],"check":{"mode":"number","value":6.0,"tolerance":6.000000000000001e-05}},{"id":"IBAI-2.1-P11","level":"Foundation","prompt":"Which statement about a function is always true?","answer":"Each input has exactly one output.","solution":"The defining condition is exactly one output for each allowed input.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["Different inputs must have different outputs.","Every real number must be an input.","Each input has exactly one output.","The graph must be a straight line."],"correct":2,"check":{"mode":"choice","value":2}},{"id":"IBAI-2.1-P12","level":"Foundation","prompt":"A context uses n for the number of buses. Which is the most appropriate domain?","answer":"Non-negative integers","solution":"A count of buses is a non-negative integer.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"choices":["All real numbers","All negative integers","Non-negative integers","All irrational numbers"],"correct":2,"check":{"mode":"choice","value":2}},{"id":"IBAI-2.1-P13","level":"Foundation","prompt":"A function has points \\((0,3),(2,7),(5,12)\\). Write down \\(f(2)\\).","answer":"\\(7\\)","solution":"The point (2,7) means f(2)=7.","marks":2,"calculator":"No GDC required","command":"Write down","hint":"","tags":[],"check":{"mode":"number","value":7.0,"tolerance":7.000000000000001e-05}},{"id":"IBAI-2.1-P14","level":"Foundation","prompt":"A function has the mapping \\(4\\mapsto -9\\). Write down one preimage of \\(-9\\).","answer":"\\(4\\)","solution":"The input 4 maps to −9.","marks":2,"calculator":"No GDC required","command":"Write down","hint":"","tags":[],"check":{"mode":"number","value":4.0,"tolerance":4e-05}},{"id":"IBAI-2.1-P15","level":"Foundation","prompt":"Which graph definitely fails the vertical-line test?","answer":"A circle","solution":"Some vertical lines meet a circle twice.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["A non-vertical line","An upward parabola","A circle","An exponential curve"],"correct":2,"check":{"mode":"choice","value":2}},{"id":"IBAI-2.1-P16","level":"Application","prompt":"A taxi fare is modelled by \\(C(d)=12+3.5d\\), where d is kilometres. Calculate the fare for 18 km.","answer":"QAR \\(75\\)","solution":"C(18)=12+3.5(18)=75.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":["context","linear"],"check":{"mode":"number","value":75.0,"tolerance":0.00075}},{"id":"IBAI-2.1-P17","level":"Application","prompt":"Temperature is converted by \\(F(C)=1.8C+32\\). Find the Fahrenheit temperature corresponding to \\(37^\\circ\\text{C}\\).","answer":"\\(98.6^\\circ\\text{F}\\)","solution":"F(37)=1.8(37)+32=98.6.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":98.6,"tolerance":0.0009860000000000001}},{"id":"IBAI-2.1-P18","level":"Application","prompt":"A tank level is \\(V(t)=420-18t\\) litres for \\(0\\le t\\le20\\). Find the time when the tank contains 150 L.","answer":"\\(15\\) minutes","solution":"Solve 420−18t=150, giving t=15.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":15.0,"tolerance":0.00015000000000000001}},{"id":"IBAI-2.1-P19","level":"Application","prompt":"A streaming plan costs QAR 28 plus QAR 1.8 per film. Find the number of films when the bill is QAR 62.20.","answer":"\\(19\\) films","solution":"Solve 28+1.8n=62.2, so n=19.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":19.0,"tolerance":0.00019}},{"id":"IBAI-2.1-P20","level":"Application","prompt":"A delivery rule is \\(D(x)=9\\) for \\(0<x\\le4\\) and \\(D(x)=9+2.5(x-4)\\) for \\(4<x\\le15\\). Find \\(D(11)\\).","answer":"QAR \\(26.5\\)","solution":"Use the second branch: 9+2.5(7)=26.5.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":26.5,"tolerance":0.00026500000000000004}},{"id":"IBAI-2.1-P21","level":"Application","prompt":"A school hall has capacity 620. Attendance a is recorded as an input. State a realistic domain.","answer":"\\(a\\in\\{0,1,\\ldots,620\\}\\)","solution":"Attendance is a whole-number count between 0 and 620.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"text","accepted":["0<=a<=620","0 ≤ a ≤ 620","integers 0 to 620","{0,1,...,620}"]}},{"id":"IBAI-2.1-P22","level":"Application","prompt":"A battery model gives charge percentage \\(B(t)=18+7.5t\\). State a contextual restriction on the range.","answer":"\\(0\\le B\\le100\\)","solution":"Battery charge cannot be below 0% or above 100%.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"text","accepted":["0<=B<=100","0 ≤ B ≤ 100","0 to 100","[0,100]"]}},{"id":"IBAI-2.1-P23","level":"Application","prompt":"A medication concentration is \\(M(t)=24e^{-0.35t}\\). Calculate \\(M(4)\\).","answer":"\\(5.918\\)","solution":"Substitute t=4 and retain the full calculator value before rounding.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":5.918327134598556,"tolerance":0.01}},{"id":"IBAI-2.1-P24","level":"Application","prompt":"A printer charges \\(P(n)=45+0.32n\\) QAR for n pages. Find the output when n=250.","answer":"QAR \\(125\\)","solution":"P(250)=45+80=125.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":125.0,"tolerance":0.00125}},{"id":"IBAI-2.1-P25","level":"Application","prompt":"The height of a lift is given by \\(h(t)=3.2t+1.5\\) metres. Find the preimage of 20.7 m.","answer":"\\(6\\) seconds","solution":"Solve 3.2t+1.5=20.7.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":6.0,"tolerance":6.000000000000001e-05}},{"id":"IBAI-2.1-P26","level":"Application","prompt":"A route distance x is measured in kilometres and travel time T(x) in minutes. Interpret the units of the average rate \\(\\Delta T/\\Delta x\\).","answer":"minutes per kilometre","solution":"It measures the change in travel time for each kilometre.","marks":2,"calculator":"No GDC required","command":"Interpret","hint":"","tags":[],"check":{"mode":"text","accepted":["minutes per kilometre","min/km","minutes/km"]}},{"id":"IBAI-2.1-P27","level":"Application","prompt":"A piecewise electricity tariff is QAR 0.11 per kWh for the first 200 kWh and QAR 0.18 per additional kWh. Find the cost of 350 kWh.","answer":"QAR \\(49\\)","solution":"Cost=200(0.11)+150(0.18)=49.","marks":4,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":49.0,"tolerance":0.0004900000000000001}},{"id":"IBAI-2.1-P28","level":"Application","prompt":"A linear model \\(R(n)=1500+85n\\) gives weekly revenue in QAR for n bookings. Find n when revenue is QAR 4390.","answer":"\\(34\\) bookings","solution":"Solve 1500+85n=4390.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":34.0,"tolerance":0.00034}},{"id":"IBAI-2.1-P29","level":"Application","prompt":"A model for the diameter d of a plant stem is valid only during 0≤t≤24 weeks. Classify a prediction at t=18 and t=30.","answer":"18 weeks: interpolation; 30 weeks: extrapolation","solution":"The first input lies inside the stated domain; the second is outside it.","marks":2,"calculator":"No GDC required","command":"Classify","hint":"","tags":[],"check":{"mode":"text","accepted":["interpolation and extrapolation","18 interpolation 30 extrapolation","interpolation, extrapolation"]}},{"id":"IBAI-2.1-P30","level":"Application","prompt":"A membership fee is \\(F(m)=110+22m\\), where m is months after joining. Calculate the increase in fee from m=3 to m=9.","answer":"QAR \\(132\\)","solution":"F(9)−F(3)=22(9−3)=132.","marks":3,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":132.0,"tolerance":0.0013200000000000002}},{"id":"IBAI-2.1-P31","level":"Reasoning","prompt":"A table lists x-values 1,2,3,4 and outputs 8,8,11,13. Which conclusion is correct?","answer":"It is a function because each x has one output.","solution":"Repeated outputs do not violate the function rule.","marks":2,"calculator":"No GDC required","command":"Justify","hint":"","tags":[],"choices":["It is not a function because 8 repeats.","It is a function because each x has one output.","It is not a relation.","Its domain is {8,11,13}."],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.1-P32","level":"Reasoning","prompt":"Which restriction is required for \\(f(x)=\\sqrt{5-2x}\\)?","answer":"x≤2.5","solution":"Require 5−2x≥0, giving x≤2.5.","marks":2,"calculator":"No GDC required","command":"Determine","hint":"","tags":[],"choices":["x≥2.5","x≤2.5","x≠2.5","x>0"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.1-P33","level":"Reasoning","prompt":"For a model of the number of passengers on a bus, which output is impossible?","answer":"23.5","solution":"Passenger counts are whole numbers.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["0","17","52","23.5"],"correct":3,"check":{"mode":"choice","value":3}},{"id":"IBAI-2.1-P34","level":"Reasoning","prompt":"A graphing calculator shows no root in the default window. What should be checked first?","answer":"Check the domain and viewing window.","solution":"A root may lie outside the displayed interval or scale.","marks":2,"calculator":"No GDC required","command":"Suggest","hint":"","tags":[],"choices":["Change the formula randomly.","Declare that no root exists.","Check the domain and viewing window.","Round all coefficients."],"correct":2,"check":{"mode":"choice","value":2}},{"id":"IBAI-2.1-P35","level":"Reasoning","prompt":"Explain why the relation \\(x=y^2\\) is not y as a function of x on x>0.","answer":"For each positive x, y may be \\(\\sqrt{x}\\) or \\(-\\sqrt{x}\\).","solution":"There are two possible outputs for one input.","marks":3,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["two y values","y=plus or minus","±sqrt","vertical line"]}},{"id":"IBAI-2.1-P36","level":"Reasoning","prompt":"Which statement best interprets f(12)=47 in a contextual model?","answer":"At input 12, the model predicts output 47.","solution":"Function notation records input first and output second.","marks":2,"calculator":"No GDC required","command":"Interpret","hint":"","tags":[],"choices":["The input 47 produces output 12.","At input 12, the model predicts output 47.","f is multiplied by 12.","The domain is 47."],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.1-P37","level":"Reasoning","prompt":"A model has domain 0≤t≤8 and range 5≤h≤31. Which statement is true?","answer":"No predicted height is below 5 or above 31.","solution":"The range constrains outputs.","marks":2,"calculator":"No GDC required","command":"Interpret","hint":"","tags":[],"choices":["Every output from 0 to 8 occurs.","Inputs are heights.","No predicted height is below 5 or above 31.","The model is linear."],"correct":2,"check":{"mode":"choice","value":2}},{"id":"IBAI-2.1-P38","level":"Reasoning","prompt":"A line has slope 4.2 litres per minute. Explain what the number 4.2 means.","answer":"The output increases by 4.2 litres for each additional minute.","solution":"Include both the change and its units.","marks":2,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["increases by 4.2 litres per minute","4.2 l/min","each minute 4.2"]}},{"id":"IBAI-2.1-P39","level":"Reasoning","prompt":"At x=3 two piecewise branches give different outputs and both use ≤. What is the main problem?","answer":"The relation gives two outputs at x=3.","solution":"Overlapping endpoints with different outputs violate the function rule.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["The graph must be linear.","The relation gives two outputs at x=3.","The range is empty.","The function is continuous."],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.1-P40","level":"Reasoning","prompt":"Distinguish image and preimage in one sentence.","answer":"An image is an output of a given input; a preimage is an input that produces a given output.","solution":"The terms reverse the direction of the mapping question.","marks":2,"calculator":"No GDC required","command":"Distinguish","hint":"","tags":[],"check":{"mode":"text","accepted":["image is output","preimage is input","output and input"]}},{"id":"IBAI-2.1-P41","level":"Reasoning","prompt":"A formula predicts −6.3 bicycles for a production decision. What is the best response?","answer":"Reject or revise the contextual use because the output is impossible.","solution":"A model output must be interpreted against contextual constraints.","marks":2,"calculator":"No GDC required","command":"Comment","hint":"","tags":[],"choices":["Report −6.3 exactly.","Round to −6.","Reject or revise the contextual use because the output is impossible.","Change the units to metres."],"correct":2,"check":{"mode":"choice","value":2}},{"id":"IBAI-2.1-P42","level":"Reasoning","prompt":"Which data representation best reveals a turning point?","answer":"A graph over the relevant domain","solution":"A graph shows global shape and turning behaviour.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["A verbal label alone","A graph over the relevant domain","A single function value","A unit statement"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.1-P43","level":"Reasoning","prompt":"Explain why a discrete domain should be stated for a function counting completed courses.","answer":"The number of completed courses is a whole-number count, so non-integer inputs are not meaningful.","solution":"The mathematical rule may accept decimals even though the context does not.","marks":2,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["whole numbers","integers","cannot complete fraction"]}},{"id":"IBAI-2.1-P44","level":"Reasoning","prompt":"If f(2)=9 and f(5)=9, which conclusion follows?","answer":"9 has at least two preimages.","solution":"Different inputs may share the same image.","marks":2,"calculator":"No GDC required","command":"Deduce","hint":"","tags":[],"choices":["f is not a function.","9 has at least two preimages.","2 has two images.","The domain is {9}."],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.1-P45","level":"Reasoning","prompt":"A graph displays a line segment with a closed point at x=4 and an open point at x=9. State the domain.","answer":"\\([4,9)\\)","solution":"Closed includes 4; open excludes 9.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"text","accepted":["[4,9)","4<=x<9","4 ≤ x < 9"]}},{"id":"IBAI-2.1-P46","level":"Challenge","prompt":"State the domain of \\(f(x)=\\frac{\\sqrt{2x+8}}{x^2-9}\\).","answer":"\\([-4,-3)\\cup(-3,3)\\cup(3,\\infty)\\)","solution":"Require x≥−4 and exclude denominator zeros ±3.","marks":4,"calculator":"No GDC required","command":"Determine","hint":"","tags":[],"check":{"mode":"text","accepted":["[-4,-3) union (-3,3) union (3,infinity)","x>=-4 x!=-3,3","x ≥ -4, x ≠ -3,3"]}},{"id":"IBAI-2.1-P47","level":"Challenge","prompt":"For \\(f(x)=x^2-6x+5\\) on \\(1\\le x\\le7\\), find the maximum output.","answer":"\\(12\\)","solution":"The vertex at x=3 gives the minimum −4. Endpoint outputs are f(1)=0 and f(7)=12, so the maximum is 12.","marks":4,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":12.0,"tolerance":0.00012000000000000002}},{"id":"IBAI-2.1-P48","level":"Challenge","prompt":"Find the range of \\(g(x)=\\frac{1}{x-2}+4\\).","answer":"\\(( -\\infty,4)\\cup(4,\\infty)\\)","solution":"The term 1/(x−2) can take any non-zero real value, so y cannot equal 4.","marks":4,"calculator":"GDC permitted","command":"Determine","hint":"","tags":[],"check":{"mode":"text","accepted":["y!=4","(-infinity,4) union (4,infinity)","y ≠ 4"]}},{"id":"IBAI-2.1-P49","level":"Challenge","prompt":"A piecewise model is \\(f(x)=ax+3\\) for x<2 and \\(f(x)=x^2-1\\) for x≥2. Find a so the graph is continuous at x=2.","answer":"\\(0\\)","solution":"The right value is 3. Continuity requires 2a+3=3, so a=0.","marks":4,"calculator":"No GDC required","command":"Determine","hint":"","tags":[],"check":{"mode":"number","value":0.0,"tolerance":1e-06}},{"id":"IBAI-2.1-P50","level":"Challenge","prompt":"A function \\(f(x)=3x+8\\) has domain \\(-4\\le x<6\\). Find the upper bound of its range and state whether it is attained.","answer":"\\(26\\), not attained","solution":"As x approaches 6 from below, f(x) approaches 26 but never reaches it; range is [−4,26).","marks":4,"calculator":"No GDC required","command":"Find","hint":"","tags":[],"check":{"mode":"number","value":26.0,"tolerance":0.00026000000000000003}},{"id":"IBAI-2.1-P51","level":"Challenge","prompt":"A tariff is QAR 15 for the first 3 GB and QAR 2.8 per additional GB. Find the usage when the total is QAR 43.","answer":"\\(13\\) GB","solution":"For usage above 3, solve 15+2.8(x−3)=43, giving x=13.","marks":4,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":13.0,"tolerance":0.00013000000000000002}},{"id":"IBAI-2.1-P52","level":"Challenge","prompt":"A relation is defined by \\(y=\\pm\\sqrt{16-x^2}\\). Give a domain restriction and branch that makes y a function.","answer":"For example, use \\(-4\\le x\\le4\\) and \\(y=\\sqrt{16-x^2}\\).","solution":"Choosing one branch gives one output per input.","marks":4,"calculator":"No GDC required","command":"Construct","hint":"","tags":[],"check":{"mode":"text","accepted":["-4<=x<=4 y=sqrt","upper semicircle","lower semicircle","y=+sqrt","y=-sqrt"]}},{"id":"IBAI-2.1-P53","level":"Challenge","prompt":"A linear model has f(−2)=11 and f(5)=−3. Find f(9).","answer":"\\(-11\\)","solution":"Slope=(−3−11)/(5−(−2))=−2. The rule is f(x)=−2x+7, so f(9)=−11.","marks":4,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":-11.0,"tolerance":0.00011}},{"id":"IBAI-2.1-P54","level":"Challenge","prompt":"Determine the domain of \\(h(x)=\\sqrt{7-x}+\\sqrt{x+1}\\).","answer":"\\([-1,7]\\)","solution":"Require x≤7 and x≥−1 simultaneously.","marks":4,"calculator":"No GDC required","command":"Determine","hint":"","tags":[],"check":{"mode":"text","accepted":["[-1,7]","-1<=x<=7","−1 ≤ x ≤ 7"]}},{"id":"IBAI-2.1-P55","level":"Challenge","prompt":"A function is \\(f(x)=|2x-6|+1\\). Find the sum of all preimages of 9.","answer":"\\(6\\)","solution":"|2x−6|=8 gives 2x−6=±8, so x=7 or x=−1; sum=6.","marks":4,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":6.0,"tolerance":6.000000000000001e-05}},{"id":"IBAI-2.1-P56","level":"Challenge","prompt":"For \\(f(x)=x^2\\) on all real x, explain why an inverse relation exists but an inverse function does not.","answer":"The rule is not one-to-one: x and −x have the same output, so the inverse relation gives two outputs for positive inputs.","solution":"Restricting the domain to x≥0 or x≤0 produces an inverse function.","marks":4,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["not one-to-one","two inputs same output","±sqrt"]}},{"id":"IBAI-2.1-P57","level":"Challenge","prompt":"A model \\(C(n)=38+6.5n\\) applies only to integer n from 0 to 40. Find the number of possible domain values.","answer":"\\(41\\)","solution":"The integers 0 through 40 inclusive give 41 inputs.","marks":3,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":41.0,"tolerance":0.00041000000000000005}},{"id":"IBAI-2.1-P58","level":"Challenge","prompt":"A graph has domain \\([-3,5]\\), minimum −4 and maximum 12, both attained. State the range.","answer":"\\([-4,12]\\)","solution":"Both extrema are included.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"text","accepted":["[-4,12]","-4<=y<=12","−4 ≤ y ≤ 12"]}},{"id":"IBAI-2.1-P59","level":"Challenge","prompt":"For \\(f(x)=2x^2-5\\), find the positive preimage of 45.","answer":"\\(5\\)","solution":"2x²−5=45 gives x²=25. The positive preimage is 5.","marks":3,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":5.0,"tolerance":5e-05}},{"id":"IBAI-2.1-P60","level":"Challenge","prompt":"A model predicts travel time T(d)=12+1.4d for 0≤d≤60. Explain why using T(400) is not defensible without further evidence.","answer":"It is far outside the validated domain, so it is extreme extrapolation and the linear relationship may not continue.","solution":"A numerical output alone does not validate a prediction.","marks":3,"calculator":"No GDC required","command":"Justify","hint":"","tags":[],"check":{"mode":"text","accepted":["extrapolation","outside domain","relationship may change"]}}],"quiz":[{"id":"IBAI-2.1-Q01","level":"Quiz","prompt":"Which relation is not a function?","answer":"{(4,2),(4,9),(7,1)}","solution":"The input 4 has two outputs.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["{(0,1),(1,1),(2,4)}","{(−1,3),(2,3),(5,8)}","{(4,2),(4,9),(7,1)}","y=3x−2"],"correct":2,"check":{"mode":"choice","value":2}},{"id":"IBAI-2.1-Q02","level":"Quiz","prompt":"For \\(f(x)=4x^2-3x\\), calculate \\(f(-2)\\).","answer":"\\(22\\)","solution":"4(4)+6=22.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":22.0,"tolerance":0.00022}},{"id":"IBAI-2.1-Q03","level":"Quiz","prompt":"State the domain of \\(g(x)=\\sqrt{9-x}\\).","answer":"\\(x\\le9\\)","solution":"Require 9−x≥0.","marks":2,"calculator":"No GDC required","command":"State","hint":"","tags":[],"check":{"mode":"text","accepted":["x<=9","x ≤ 9","(-infinity,9]"]}},{"id":"IBAI-2.1-Q04","level":"Quiz","prompt":"Find the x-intercept of \\(y=6-1.5x\\).","answer":"\\(4\\)","solution":"Set y=0 and solve.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":4.0,"tolerance":4e-05}},{"id":"IBAI-2.1-Q05","level":"Quiz","prompt":"A rule is \\(P(t)=10\\) for t≤3 and \\(P(t)=10+2(t−3)\\) for t>3. Find P(8).","answer":"\\(20\\)","solution":"Use the second branch.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":20.0,"tolerance":0.0002}},{"id":"IBAI-2.1-Q06","level":"Quiz","prompt":"A function maps −5→2. State the corresponding point on the inverse relation.","answer":"\\((2,-5)\\)","solution":"Swap input and output.","marks":2,"calculator":"No GDC required","command":"Write down","hint":"","tags":[],"check":{"mode":"text","accepted":["(2,-5)","2,-5"]}},{"id":"IBAI-2.1-Q07","level":"Quiz","prompt":"A charge model is C(n)=24+1.75n. Find n when C=52.","answer":"\\(16\\)","solution":"Solve 1.75n=28.","marks":2,"calculator":"GDC permitted","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":16.0,"tolerance":0.00016}},{"id":"IBAI-2.1-Q08","level":"Quiz","prompt":"Which domain is appropriate for the number of goals in a match?","answer":"Non-negative integers","solution":"Goals are counted in non-negative whole numbers.","marks":2,"calculator":"No GDC required","command":"Identify","hint":"","tags":[],"choices":["All real numbers","Non-negative integers","Negative integers","0<x<1"],"correct":1,"check":{"mode":"choice","value":1}},{"id":"IBAI-2.1-Q09","level":"Quiz","prompt":"State the range of y=−3x+10 for 0≤x≤4.","answer":"\\([-2,10]\\)","solution":"Endpoint outputs are 10 and −2.","marks":2,"calculator":"No GDC required","command":"Determine","hint":"","tags":[],"check":{"mode":"text","accepted":["[-2,10]","-2<=y<=10","−2 ≤ y ≤ 10"]}},{"id":"IBAI-2.1-Q10","level":"Quiz","prompt":"For \\(f(x)=|x-7|\\), find the sum of the two preimages of 5.","answer":"\\(14\\)","solution":"x=12 or 2; sum 14.","marks":2,"calculator":"No GDC required","command":"Calculate","hint":"","tags":[],"check":{"mode":"number","value":14.0,"tolerance":0.00014000000000000001}},{"id":"IBAI-2.1-Q11","level":"Quiz","prompt":"Explain why a circle is not y as a function of x.","answer":"Most interior x-values correspond to an upper and a lower y-value.","solution":"A vertical line meets it twice.","marks":3,"calculator":"No GDC required","command":"Explain","hint":"","tags":[],"check":{"mode":"text","accepted":["vertical line","two y values","upper and lower"]}},{"id":"IBAI-2.1-Q12","level":"Quiz","prompt":"A model valid on 5≤x≤20 is used at x=14 and x=27. Classify the two predictions.","answer":"14 is interpolation; 27 is extrapolation.","solution":"Only 14 lies inside the validated domain.","marks":3,"calculator":"No GDC required","command":"Classify","hint":"","tags":[],"check":{"mode":"text","accepted":["interpolation extrapolation","14 interpolation 27 extrapolation"]}}],"exam":[{"id":"U2-2.1-T1","style":"Paper 2 · modelling","title":"Urban delivery fee model","calculator":"GDC expected","total_marks":11,"context":"A delivery service models the fee C, in QAR, for a trip of d kilometres by the continuous piecewise function \\[C(d)=\\begin{cases}12+1.8d,&0\\le d\\le10,\\\\30+0.9(d-10),&10<d\\le30.\\end{cases}\\]","parts":[{"label":"a","prompt":"Calculate C(8) and C(25).","marks":3,"answer":"\\(C(8)=26.4\\) QAR and \\(C(25)=43.5\\) QAR.","markscheme":"M1 correct branch for each input; A1 26.4; A1 43.5."},{"label":"b","prompt":"State the contextual domain and range of C.","marks":3,"answer":"Domain \\(0\\le d\\le30\\); range \\(12\\le C\\le48\\).","markscheme":"A1 domain; M1 endpoint outputs; A1 range."},{"label":"c","prompt":"Show that the two rules agree at d=10 and interpret this result.","marks":3,"answer":"Both rules give 30 QAR, so the tariff has no jump at the boundary.","markscheme":"M1 substitute 10 in each expression; A1 equality; A1 contextual interpretation."},{"label":"d","prompt":"Explain one limitation of this model for a delivery platform.","marks":2,"answer":"For example, it ignores traffic, waiting time, surge pricing, tolls or trips beyond 30 km.","markscheme":"R1 valid limitation; R1 effect on validity."}]},{"id":"U2-2.1-T2","style":"Paper 1/2 bridge","title":"Reservoir sensor and inverse interpretation","calculator":"GDC expected","total_marks":12,"context":"A sensor estimates the water depth h metres at time t hours using \\(h(t)=\\sqrt{36-3t}\\), for the emptying phase of a reservoir.","parts":[{"label":"a","prompt":"Determine the largest contextual domain of t.","marks":3,"answer":"\\(0\\le t\\le12\\).","markscheme":"M1 radicand condition; A1 t≤12; A1 contextual lower bound t≥0."},{"label":"b","prompt":"Find the range of h on this domain.","marks":2,"answer":"\\(0\\le h\\le6\\).","markscheme":"M1 endpoint/monotonic reasoning; A1 range."},{"label":"c","prompt":"Find an expression for the inverse function and state its domain.","marks":4,"answer":"\\(h^{-1}(x)=\\frac{36-x^2}{3}\\), for \\(0\\le x\\le6\\).","markscheme":"M1 swap variables; M1 square and solve; A1 formula; A1 inverse domain."},{"label":"d","prompt":"Interpret \\(h^{-1}(2)\\) in context and calculate it.","marks":3,"answer":"\\(h^{-1}(2)=32/3\\approx10.7\\) hours; it is the time when the depth is 2 m.","markscheme":"M1 substitution; A1 value; A1 interpretation with units."}]},{"id":"U2-2.1-T3","style":"Investigation · communication","title":"Choosing a valid representation","calculator":"GDC expected","total_marks":11,"context":"A school records the number n of students entering a study centre and the total noise level L. For n=0,5,10,15,20 the measured values are 34,42,49,61,74 decibels.","parts":[{"label":"a","prompt":"Construct a labelled scatter plot using technology and describe the association.","marks":3,"answer":"An increasing, approximately non-linear association.","markscheme":"A1 labelled axes; A1 plotted points; R1 description."},{"label":"b","prompt":"Explain why the table alone does not define a continuous function for every real n.","marks":2,"answer":"Only sampled integer inputs are given; interpolation between measurements is a modelling decision.","markscheme":"R1 sampled/discrete inputs; R1 model assumption."},{"label":"c","prompt":"State a defensible contextual domain and explain it.","marks":2,"answer":"For example, integers \\(0\\le n\\le20\\) for the observed study-centre capacity.","markscheme":"A1 domain; R1 contextual justification."},{"label":"d","prompt":"Write a short evaluation comparing a table, graph and formula as representations for this situation.","marks":4,"answer":"The table preserves observations, the graph reveals trend and anomalies, and a formula enables prediction but introduces assumptions and error.","markscheme":"Up to 4 marks for a balanced comparison referring to all three representations."}]}],"counts":{"slides":64,"practice":60,"quiz":12,"exam":3},"rights":{"student_content":"Original ECHS-authored instructional and assessment content","private_bank_policy":"No source-bank prompt, canonical ID, provenance record or rights record is embedded in public lesson assets."}};
